    """Group rows, columns, and diagonals, rather than walking from run starts."""
    lines = [list(row) for row in board]
    lines.extend([board[r][c] for r in range(SIZE)] for c in range(SIZE))
    for offset in range(-SIZE + 1, SIZE):
